#!/usr/bin/env python3
"""Build the self-contained Tillamook workbench. Python standard library required.

Optional --figure additionally renders the three-architecture comparison with
Matplotlib. The HTML performs no network requests and reads embedded evidence.
"""
import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ARCHES = ["straight-ramp", "switchback-ramp", "elevator-and-stair-allowance"]
ARCH_LABELS = ["Straight ramps", "Switchback ramps", "Elevator + stairs allowance"]


def read(name):
    return json.loads((ROOT / name).read_text(encoding="utf-8"))


def ranking(row):
    h = row["hits"]
    return tuple(len(h[k]) for k in ["building_ids", "vehicle_centerline_ids", "building_ids_at_3m_sensitivity", "vehicle_width_proxy_ids", "environment_ids", "canopy_proxy_ids"]) + (row["id"],)


def payload():
    atlas = read("data/atlas-subset.json")
    study = read("site-report.json")
    engineering = read("engineering-report.json")
    bridge = read("examples/bridge-example-report.json")
    trusses = []
    for name in ["service-24m-plane", "prejoin-12m-plane"]:
        model = read("examples/" + name + ".json")
        result = read("examples/" + name + "-result.json")
        trusses.append({"model": model, "result": {k: result[k] for k in ["nodal_displacements", "members", "supported_rigidity_rank", "free_dof_count", "status"]}})
    hm = read("data/hazards/manifest.json")
    hazards = []
    for layer in hm["layers"]:
        if layer.get("clip_status") == "complete":
            actual_hash = hashlib.sha256((ROOT / "data/hazards" / layer["clipped_file"]).read_bytes()).hexdigest()
            if actual_hash != layer["clipped_sha256"]:
                raise ValueError("Clipped hazard data do not match the audit manifest: " + layer["key"])
            data = read("data/hazards/" + layer["clipped_file"])
            hazards.append({"key": layer["key"], "label": layer["label"], "features": data["features"]})
    hazard_report = None
    if (ROOT / "hazard-report.json").exists():
        raw = read("hazard-report.json")
        catalog = raw.get("feature_catalog", {})
        entries = {}
        for row in raw.get("scenarios", []):
            entries[row["scenario_id"]] = [{"key": layer["key"], "status": layer["status"], "covered": layer.get("all_footprints_within_query_bounds", False),
                "hits": [{"id": hit["feature_id"], "label": catalog.get(hit["feature_id"], hit).get("label", "Unclassified feature"), "footprints": hit.get("footprint_ids", [])} for hit in layer.get("intersections", [])]} for layer in row["layers"]]
        hazard_report = {"summary": raw.get("summary"), "scenarios": entries}
    source_files = ["data/atlas-subset.json", "site-report.json", "engineering-report.json", "examples/bridge-example-report.json", "data/hazards/manifest.json"]
    for name in ["service-24m-plane", "prejoin-12m-plane"]:
        source_files.extend(["examples/" + name + ".json", "examples/" + name + "-result.json"])
    if hazard_report:
        source_files.append("hazard-report.json")
    no_hit = [r for r in study["scenarios"] if not r["hits"]["building_ids"] and not r["hits"]["vehicle_centerline_ids"]]
    return {"atlas": {k: atlas[k] for k in ["bounds", "origin", "counts", "buildings", "parcels", "streets", "canopy", "areas", "terrain", "provenance"]},
        "study": study, "engineering": {k: engineering[k] for k in ["candidate_count", "strict_feasible_count", "parameter_domain", "assumptions", "not_resolved", "flat_ground_access_example"]},
        "bridge": bridge, "trusses": trusses, "hazards": hazards, "hazardReport": hazard_report,
        "summary": {"total": len(study["scenarios"]), "conflict": len(study["scenarios"]) - len(no_hit), "noHit": len(no_hit), "sensitive": sum(bool(r["hits"]["building_ids_at_3m_sensitivity"]) for r in no_hit)},
        "sourceHashes": {name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest() for name in source_files}}


