def render_figure(data):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.patches import Polygon
    atlas, study = data["atlas"], data["study"]
    rows = [min((r for r in study["scenarios"] if r["site_id"] == "main-7th" and r["width_hypothesis_m"] == 12 and r["architecture"] == arch), key=ranking) for arch in ARCHES]
    points = [p for row in rows for f in row["footprints"] for p in f["ring"]]
    xmin, xmax = min(p[0] for p in points)-22, max(p[0] for p in points)+22
    ymin, ymax = min(p[1] for p in points)-18, max(p[1] for p in points)+18
    # A common aspect, scale and coordinate window make approach footprints comparable.
    cx=(xmin+xmax)/2; halfwidth=max((xmax-xmin)/2,(ymax-ymin)*0.40)
    xmin,xmax=cx-halfwidth,cx+halfwidth
    fig, axes = plt.subplots(1,3,figsize=(15,8),facecolor="#f4f3ed")
    fig.subplots_adjust(left=.035,right=.985,top=.79,bottom=.16,wspace=.07)
    fig.text(.035,.95,"TILLAMOOK  /  BASE AND ACCESS FOOTPRINTS",fontsize=11,color="#006d77",weight="bold")
    fig.text(.035,.898,"The access arrangement changes what fits.",fontsize=25,color="#183331",weight="bold")
    fig.text(.035,.853,"Main Avenue at 7th Street · 12 m assumed road envelope · best-ranked placement for each architecture",fontsize=12,color="#60706c")
    for ax,row,label in zip(axes,rows,ARCH_LABELS):
        ax.set_facecolor("#eef0e8")
        for f in atlas["parcels"]:
            for ring in f["rings"]:
                ax.add_patch(Polygon(ring,closed=True,fill=False,edgecolor="#c4bd9f",linewidth=.45))
        for street in atlas["streets"]:
            pts=street["p"]; ax.plot([p[0] for p in pts],[p[1] for p in pts],color="#7d8981",linewidth=.8)
        direct=set(row["hits"]["building_ids"])
        for f in atlas["buildings"]:
            for i,ring in enumerate(f["rings"]):
                ax.add_patch(Polygon(ring,closed=True,facecolor=("#dca08f" if f["id"] in direct else "#cbd0c5") if i==0 else "#eef0e8",edgecolor="#ad4e39" if f["id"] in direct else "#99a092",linewidth=.5))
        bases=[f for f in row["footprints"] if f["kind"]=="base"]
        centres=[[sum(p[i] for p in f["ring"])/len(f["ring"]) for i in [0,1]] for f in bases]
        ax.plot([p[0] for p in centres],[p[1] for p in centres],color="#25888a",linewidth=4)
        for f in row["footprints"]:
            ax.add_patch(Polygon(f["ring"],closed=True,facecolor="#274b72" if f["kind"]=="base" else "#acd9d2",edgecolor="#203f61" if f["kind"]=="base" else "#006d77",linewidth=1.2,zorder=5))
        ax.set_xlim(xmin,xmax);ax.set_ylim(ymin,ymax);ax.set_aspect("equal");ax.set_xticks([]);ax.set_yticks([])
        for spine in ax.spines.values():spine.set_color("#d7ded6")
        ax.set_title(label,loc="left",fontsize=13,color="#183331",pad=12,weight="bold")
        ax.text(.04,.97,f"Offset {row['station_offset_m']:+d} m · 23 m assumed span",transform=ax.transAxes,fontsize=9,color="#60706c",va="top",bbox=dict(facecolor="#fffef9",edgecolor="none",alpha=.9,pad=4))
        ax.annotate("N",xy=(.94,.92),xytext=(.94,.81),xycoords="axes fraction",ha="center",fontsize=10,color="#183331",arrowprops=dict(arrowstyle="-|>",color="#183331",lw=1))
        x0=xmin+(xmax-xmin)*.07;y0=ymin+(ymax-ymin)*.055
        ax.plot([x0,x0+25],[y0,y0],color="#183331",lw=2);ax.text(x0,y0+3,"25 m",fontsize=8,color="#183331")
        ax.text(0,-.055,f"{len(row['hits']['building_ids'])} building · {len(row['hits']['vehicle_centerline_ids'])} road centerline intersections",transform=ax.transAxes,fontsize=9.5,color="#183331",weight="bold",va="top")
        ax.text(0,-.102,f"{len(row['hits']['building_ids_at_3m_sensitivity'])} buildings at 3 m sensitivity · {len(row['hits']['parcel_ids'])} parcel parts",transform=ax.transAxes,fontsize=9,color="#60706c",va="top")
    fig.text(.035,.065,"Navy: base envelope   •   Teal fill: access allowance   •   Teal stroke: schematic span link   •   Red: intersected building   •   Gray lines: road centerlines",fontsize=9.5,color="#476359")
    fig.text(.035,.031,"Declared layouts, not approved sites. Widths are assumed; the 3 m sensitivity is not a measured position error.  © OpenStreetMap contributors · DOGAMI · ODOT",fontsize=8.5,color="#60706c")
    fig.savefig(ROOT/"site-comparison.png",dpi=190,facecolor=fig.get_facecolor());plt.close(fig)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--figure",action="store_true",help="Also generate the Matplotlib comparison PNG (optional dependency).")
    args=parser.parse_args()
    data=payload()
    encoded=json.dumps(data,separators=(",",":"),ensure_ascii=False).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026")
    target=ROOT/"workbench.html"
    target.write_text(HTML.replace("__DATA__",encoded),encoding="utf-8")
    print(f"Wrote {target.name}: {target.stat().st_size:,} bytes; {len(data['study']['scenarios'])} scenarios")
    if args.figure:
        render_figure(data)
        print("Wrote site-comparison.png")


if __name__=="__main__":main()
